const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || 'replace-with-a-high-entropy-64-character-hex-secret';

const headers = $input.first().json.headers;
const body = $input.first().json.body;

const rawSignature = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'];
if (!rawSignature) {
  throw new Error('Missing X-LendLoop-Signature header');
}

const expectedSig = crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex');

const sigBuf = Buffer.from(rawSignature.replace('sha256=', ''), 'hex');
const expBuf = Buffer.from(expectedSig, 'hex');

if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('HMAC signature verification failed');
}

return [{
  json: {
    verified: true,
    event: body.eventType,
    requestId: body.requestId,
    toolName: body.toolName,
    ownerId: body.ownerId,
    borrowerId: body.borrowerId,
    startDate: body.startDate,
    endDate: body.endDate,
    timestamp: body.timestamp
  }
}];
